from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'assets/district'
OUT.mkdir(exist_ok=True)
COLORS={'blue':'#76bed8','coral':'#e8978d','green':'#86bda5','gold':'#dfb181','purple':'#b3a3cb'}
def svg(name,w,h,body,color='blue'):
    c=COLORS[color]
    text=f'''<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}">
    <defs><linearGradient id="shell" x2=".2" y2="1"><stop stop-color="#fffdf5"/><stop offset=".6" stop-color="#eef5f4"/><stop offset="1" stop-color="#b9d3dc"/></linearGradient><linearGradient id="accent" x2=".3" y2="1"><stop stop-color="#e6f8f3"/><stop offset=".4" stop-color="{c}"/><stop offset="1" stop-color="#56809a"/></linearGradient><linearGradient id="danger" x2="0" y2="1"><stop stop-color="#ffe6cc"/><stop offset="1" stop-color="#e18c89"/></linearGradient></defs>
    <g stroke="#668caa" stroke-width="2.4" stroke-linejoin="round" stroke-linecap="round">{body}</g></svg>'''
    (OUT/(name+'.svg')).write_text(text,encoding='utf-8')
# All silhouettes are compact and obey existing first-jump clearance budgets.
