for name,color,glyph in [('spring','blue','M39 22 50 12 61 22'),('delivery','gold','M39 12v12h22V12Z'),('charge','green','m55 8-14 15h11l-4 10 13-16H50Z'),('vent','green','M40 16h20m-20 8h20'),('relay','purple','m39 21 8 6 15-16')]:
    svg(name,100,50,f'''<rect x="4" y="21" width="92" height="25" rx="12" fill="url(#shell)"/><ellipse cx="50" cy="22" rx="43" ry="15" fill="url(#accent)"/><path d="{glyph}" fill="none" stroke="#fff" stroke-width="4"/><path d="M20 40h60" stroke="{COLORS[color]}" stroke-width="4"/>''',color)
