    svg(name,160,80,'''<path d="M33 45 12 53l13 10h28m73-20 23 12-15 9h-21" fill="url(#accent)"/><ellipse cx="80" cy="35" rx="60" ry="24" fill="url(#shell)"/><path d="M43 21c19-11 55-9 75 3" stroke="#fff" stroke-width="5" fill="none"/><rect x="61" y="54" width="38" height="17" rx="7" fill="url(#accent)"/><path d="M69 60h5m13 0h5" stroke="#fff" stroke-width="3"/><path d="M38 39h84" stroke="#76bed8" stroke-width="3"/>''',color)
